abstract class Notification{
    protected String recipient;
    protected int msgLength;
    double cost;
    Notification(String recipient, int msgLength){
        this.recipient=recipient;
        this.msgLength=msgLength;
    }
    abstract double calcCost();
    void displayLog(){
        System.out.println("Notification sent to: "+recipient);
        System.out.println("Total Cost: "+cost);
    }
}
class EmailNotification extends Notification{
    EmailNotification(String recipient, int msgLength){
        super(recipient, msgLength);
    }
    double calcCost(){
        cost=msgLength*0.10;
        return cost;
    }
}
