public class Main{
    public static void main(String args[]){
        Scanner sc = new Scanner(System.in);
        String type = sc.nextLine();
        String recipient = sc.nextLine();
        int msgLength = sc.nextInt();
        if ((!type.equals("Email") && !type.equals("SMS")) || recipient.isEmpty() || msgLength <= 0){
            System.out.println("Invalid Input");
            return;
        }
        Notification obj;
        if( type.equals("Email")){
            obj = new EmailNotification(recipient, msgLength);
            obj.displayLog();
            System.out.printf("Total Cost: %.1f\n", obj.calcCost());
        }else if( type.equals("SMS")){
            obj = new SMSNotification(recipient, msgLength);
            obj.displayLog();
            System.out.printf("Total Cost: %.1f\n", obj.calcCost());
        }else{
            System.out.println("Invalid Input");
        }
    }
}

